-- Gold table of the orders pipeline for the dev target.
-- Generated by the sp-dynamo-firehose-s3 skill. The gold job writes to this
-- table but never creates it, so run this before the job's first run.
CREATE TABLE IF NOT EXISTS `dev`.`gold`.`orders` (
  `id` INT COMMENT "Order identifier.",
  `created_at` TIMESTAMP COMMENT "UTC timestamp when an order was created.",
  `amount` DECIMAL(22, 2) COMMENT "Order amount in dollars.",
  `status` STRING COMMENT "Order status.",
  `address__city` STRING COMMENT "City from where the order was placed.",
  `address__state` STRING COMMENT "State from where the order was placed.",
  `address__zip_code` STRING COMMENT "Zip code from where the order was placed.",
  `_event_name` STRING COMMENT "DynamoDB change type: INSERT, MODIFY, or REMOVE.",
  `_event_id` STRING COMMENT "Unique ID of the DynamoDB change event.",
  `_event_timestamp` TIMESTAMP COMMENT "Approximate time DynamoDB made the change, from the event's ApproximateCreationDateTime.",
  `_ingested_at` TIMESTAMP COMMENT "Time the bronze job loaded the record.",
  `_file_path` STRING COMMENT "S3 path of the Firehose file the record came from.",
  `_file_modification_time` TIMESTAMP COMMENT "Time the Firehose file the record came from was last modified in S3."
)
USING DELTA
COMMENT "Pipeline to ingest orders. The latest version of every primary key, merged from silver.";
